import {mountFigure} from './figure-effects.js';
import {workflowLessons,bioGlossary} from './omics-workflow-lessons.js';
import {bioSources} from './omics-expansion.js';
import {analysis} from './omics-analysis-data.js';
import {labSpecs,labResult} from './omics-analysis-lab.js';
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function analysisReader(o){const a=analysis[o.id],src=bioSources[a.ref];return `<section class="bio-reader" id="omics-bio"><span class="eyebrow">BIOINFORMATICS / 从文件到结论</span><h3>${o.name}的数据怎样分析？</h3><p><strong>先准备：</strong>${a.input}</p><ol>${a.workflow.map((s,i)=>`<li><strong>${s}</strong>${workflowLessons[o.id]?`<p>${workflowLessons[o.id][i]}</p>`:''}</li>`).join('')}</ol><p><strong>得到的结果：</strong>${a.result}</p><details class="bio-glossary"><summary>第一次读分析流程？先认识文件和术语</summary>${bioGlossary.map(([t,d])=>`<p><strong>${t}</strong> ${d}</p>`).join('')}</details><h4>本方向的质控重点</h4><ul>${a.qc.map(s=>`<li>${s}</li>`).join('')}</ul><p class="bio-contrast">${a.compare}</p><a href="${src.url}" target="_blank" rel="noopener noreferrer">${src.label} · 官方方法与工具说明 ↗</a><p class="bio-small">链接提供相关方法入门，未必覆盖本方向全部分支；真实项目需按实验设计选择参数、参考版本和适配工具。页面不执行真实数据分析。</p><button class="outline" data-mode="connections">打开本方向生信演示 ↑</button></section>`;}
export class AnalysisStudio{
 constructor(root,o){this.root=root;this.o=o;this.a=analysis[o.id];this.spec=labSpecs[this.a.lab];this.step=0;this.value=this.spec[5];this.choice=0;this.abort=new AbortController();root.addEventListener('click',e=>{const b=e.target.closest('button');if(b?.dataset.bioStep!==undefined){this.step=+b.dataset.bioStep;this.render();}if(b?.dataset.bioChoice!==undefined){this.choice=+b.dataset.bioChoice;this.render();}if(b?.hasAttribute('data-bio-reset')){this.value=this.spec[5];this.choice=0;this.render();}},{signal:this.abort.signal});root.addEventListener('input',e=>{if(e.target.matches('[data-bio-value]')){this.value=+e.target.value;this.draw();}},{signal:this.abort.signal});this.render();}
 destroy(){this.abort.abort();}
 getState(){return{topic:this.o.id,step:this.step,value:this.value,choice:this.choice,lab:this.a.lab};}
 render(){const a=this.a,s=this.spec;this.root.innerHTML=`<div class="bio-studio"><span class="eyebrow">BIOINFORMATICS WORKBENCH</span><h2>${this.o.name} · 从输入到结果</h2><div class="bio-input"><small>真实分析需要的输入</small><p>${a.input}</p></div><div class="bio-steps">${a.workflow.map((x,i)=>`<button data-bio-step="${i}" aria-pressed="${i===this.step}"><b>0${i+1}</b>${x.split('并')[0].split('及')[0]}</button>`).join('')}</div><div class="bio-current" aria-live="polite"><strong>第 ${this.step+1} 步</strong><p>${a.workflow[this.step]}</p><p>${workflowLessons[this.o.id]?.[this.step]||[a.input,a.qc[0],a.qc[1],a.compare][this.step]}</p><small>${this.step<2?'这一步影响后续数据的可比较性与可信度。':a.result}</small></div><div class="bio-lab"><span class="eyebrow">可计算的教学数据 · 非真实样本</span><h3>${s[0]}</h3><p>${this.o.name}在这里练习的重点：${a.compare}</p><div class="bio-choices">${s[6].map((x,i)=>`<button data-bio-choice="${i}" aria-pressed="${this.choice===i}">${x}</button>`).join('')}</div><label class="bio-slider">${s[1]} <output data-bio-output>${this.value}</output><input data-bio-value type="range" min="${s[2]}" max="${s[3]}" step="${s[4]}" value="${this.value}" aria-label="${s[1]}"></label><div data-bio-chart></div><div data-bio-insight class="bio-insight" aria-live="polite"></div><details open><summary>核对数据与计算</summary><div data-bio-table class="comparison-scroll"></div></details><button class="outline" data-bio-reset>重置演示</button></div><section class="bio-qc"><h3>拿到自己的数据，先查这些</h3>${a.qc.map((x,i)=>`<p><b>0${i+1}</b>${x}</p>`).join('')}</section><a class="bio-source" href="${bioSources[a.ref].url}" target="_blank" rel="noopener noreferrer">${bioSources[a.ref].label} ↗</a><p class="bio-small">软件与平台会更新，请以链接中的适用输入和说明为准；课堂演示没有运行真实比对、峰调用或统计检验。</p><button class="primary" data-practice>本方向 3 道练习 →</button></div>`;this.draw();}
 draw(){const r=labResult(this.a.lab,this.value,this.choice);this.root.querySelector('[data-bio-output]').value=this.value;this.root.querySelector('[data-bio-insight]').textContent=r.summary;this.root.querySelector('[data-bio-table]').innerHTML=`<table class="comparison-table"><thead><tr>${r.headers.map(x=>`<th>${esc(x)}</th>`).join('')}</tr></thead><tbody>${r.rows.map(row=>`<tr>${row.map(x=>`<td>${esc(x)}</td>`).join('')}</tr>`).join('')}</tbody></table>`;const captions={variant:'位点编号 → · 替代等位读段数',counts:this.choice?'基因编号 → · 样本 B 的 CPM':'基因编号 → · 样本 B 的原始计数',peaks:'区域编号 → · 达到阈值的信号',methyl:'CpG 编号 → · 修饰比例 %',enrichment:this.choice?'条件 A / B → · IP/input 比值':'条件 A / B → · IP 信号',occupancy:'RNA / RPF / 当前读数 → · 变化倍数',features:'特征编号 → · 样本/空白比值',peptides:'肽段编号 → · 当前纳入的信号',ptm:'位点 / 总蛋白 / 当前读数 → · 变化倍数',splicing:'样本 A / B → · 包含转录本数',lengths:'读段编号 → · 剪后长度 nt',taxa:'成员 A / B → · 相对比例 %',flux:'时间 → · 标记比例 %',units:this.choice?'样本 A / B → · 每质量浓度':'样本 A / B → · 元素总量',coverage:'参考坐标 → · 通过质量阈值的覆盖',clones:'克隆编号 → · 细胞比例 %',profiles:'位置或时间索引 → · 信号（任意单位）'};let body='';if(this.a.lab==='counts'){const max=Math.max(...r.rows.flatMap(x=>[x[1],x[2]]),1);body='<path d="M50 35V235H510" fill="none" stroke="#afc5d5"/><text x="85" y="23" fill="#558fc5">● 样本 A</text><text x="205" y="23" fill="#d28380">● 样本 B</text>';r.rows.forEach((row,i)=>{for(let j=1;j<=2;j++){const x=90+i*135+(j-1)*40,h=row[j]/max*165;body+=`<rect x="${x}" y="${230-h}" width="30" height="${h}" rx="6" fill="${j===1?'#558fc5':'#d28380'}"><title>${row[0]} · 样本 ${j===1?'A':'B'}：${row[j]}</title></rect><text x="${x+15}" y="${221-h}" text-anchor="middle">${row[j]}</text>`;}body+=`<text x="${125+i*135}" y="253" text-anchor="middle">${row[0]}</text>`;});body+=`<text x="270" y="285" text-anchor="middle">同一基因，两份样本 · ${this.choice?'CPM':'原始计数'}</text>`;}else if(['flux','profiles'].includes(this.a.lab)){const flux=this.a.lab==='flux',max=flux?100:10,n=flux?11:5,x=i=>65+i/(n-1)*420,y=v=>230-v/max*170;const series=flux?[r.values]:[r.rows.map(r=>r[1]),r.rows.map(r=>r[2])];body='<path d="M65 40V230H495" fill="none" stroke="#afc5d5"/>';for(let j=0;j<series.length;j++){const values=series[j],color=['#558fc5','#d28380'][j],path=values.map((v,i)=>(i?'L':'M')+x(i)+','+y(v)).join(' ');body+=`<g data-series="${j}" opacity="${flux||j===this.choice?1:.3}"><path d="${path} L495 230L65 230Z" fill="${color}" opacity=".08"/><path d="${path}" fill="none" stroke="${color}" stroke-width="3"/>`;values.forEach((v,i)=>body+=`<circle cx="${x(i)}" cy="${y(v)}" r="3.5" fill="${color}"><title>${flux?'时间 '+i/2:'条件 '+(j?'B':'A')+' · 索引 '+i}：${v.toFixed(2)}${flux?'%':''}</title></circle>`);const index=flux?this.value*2:this.value;body+=`<circle cx="${x(index)}" cy="${y(values[index])}" r="7" fill="${color}" stroke="white" stroke-width="2"><title>当前选择：${values[index].toFixed(2)}${flux?'%':''}</title></circle></g>`;}
 for(let i=0;i<n;i++)body+=`<text x="${x(i)}" y="253" text-anchor="middle">${flux?i/2:i}</text>`;for(const v of [0,max/2,max])body+=`<text x="50" y="${y(v)+4}" text-anchor="end">${v}</text>`;body+=`<path d="M${x(flux?this.value*2:this.value)} 40V230" fill="none" stroke="#879eb3" stroke-dasharray="3 5"/><text x="270" y="22" text-anchor="middle">${flux?'标记比例随时间变化':'湖蓝：A · 珊瑚粉：B · 总量相同，峰位置不同'}</text><text x="270" y="285" text-anchor="middle">${captions[this.a.lab]}</text>`;}else if(this.a.lab==='pairing'){const right=['C3','C1','C4','C2'];body='<text x="110" y="25" text-anchor="middle">RNA 条码</text><text x="430" y="25" text-anchor="middle">另一模态条码</text>';r.rows.forEach(([id,target,ok],i)=>{const y=65+i*55,yy=65+right.indexOf(target)*55;body+=`<path d="M155 ${y}L385 ${yy}" stroke="${ok==='是'?'#58a28a':'#ce8b9f'}" stroke-width="3"/><rect x="65" y="${y-18}" width="90" height="36" rx="8" fill="#dce6ec"/><text x="110" y="${y+5}" text-anchor="middle">${id}</text>`;});right.forEach((id,i)=>body+=`<rect x="385" y="${47+i*55}" width="90" height="36" rx="8" fill="#e3e3e9"/><text x="430" y="${70+i*55}" text-anchor="middle">${id}</text>`);body+='<text x="270" y="285" text-anchor="middle">连接显示当前配对 · 核对两端条码是否相同</text>';}else if(r.matrix){const mx=Math.max(...r.matrix.flat(),1);r.matrix.forEach((row,i)=>row.forEach((v,j)=>{const w=Math.min(55,400/row.length),h=Math.min(36,220/r.matrix.length);body+=`<rect x="${65+j*w}" y="${24+i*h}" width="${w-3}" height="${h-3}" rx="3" fill="hsl(204 50% ${96-v/mx*45}%)"><title>行 ${i+1} / 列 ${j+1}：${v.toFixed(2)}</title></rect>`;}));body+='<text x="260" y="270" text-anchor="middle">格子：行 × 列；深色表示较高数值</text>';}else if(r.edges){const pos={A:[80,80],B:[220,45],C:[130,220],D:[350,170],E:[450,65]};body=r.edges.map(([a,b,v])=>`<path d="M${pos[a]}L${pos[b]}" stroke="#a5b4bc" stroke-width="${1+v*5}"/>`).join('')+Object.entries(pos).map(([id,[x,y]])=>`<circle cx="${x}" cy="${y}" r="20" fill="#86a8cb"/><text x="${x}" y="${y+5}" text-anchor="middle">${id}</text>`).join('');}else {const vals=r.values.length?r.values:r.rows.map((_,i)=>i+1),max=Math.max(...vals,1),w=Math.min(65,420/vals.length);body=`<path d="M45 20V235H500" fill="none" stroke="#b5c2c9"/>`+vals.map((v,i)=>`<rect x="${65+i*w}" y="${230-v/max*175}" width="${w-9}" height="${v/max*175}" fill="${i%2?'#c7a479':'#64a2c0'}" rx="3"><title>${captions[this.a.lab]} · 第 ${i+1} 项：${Number.isInteger(v)?v:v.toFixed(2)}</title></rect><text x="${65+i*w+(w-9)/2}" y="${218-v/max*175}" text-anchor="middle">${Number.isInteger(v)?v:v.toFixed(2)}</text><text x="${65+i*w+(w-9)/2}" y="253" text-anchor="middle">${this.a.lab==='flux'?i/2:this.a.lab==='profiles'?i:i+1}</text>`).join('')+`<text x="265" y="282" text-anchor="middle">${captions[this.a.lab]||'条目编号 → · 当前读数'}</text>`;}
 mountFigure(this.root.querySelector('[data-bio-chart]'),`<svg viewBox="0 0 540 300" role="img" aria-label="${this.spec[0]}教学数据图">${body}</svg>`);}
}
